// loadChunkSnapshot replays the chunk snapshot and restores the Head state from it. If there was any error returned,
// it is the responsibility of the caller to clear the contents of the Head.
func (h *Head) loadChunkSnapshot() (int, int, map[chunks.HeadSeriesRef]*memSeries, error) {
	files, err := os.ReadDir(h.opts.ChunkDirRoot)
	if err != nil {
		return 0, 0, nil, errors.Wrap(err, "find last chunk snapshot")
	}

	maxIdx, maxOffset := -1, -1
	maxFileName := ""
	for i := 0; i < len(files); i++ {
		fi := files[i]
		name := fi.Name()
		if !strings.HasPrefix(name, chunkSnapshotPrefix) {
			continue
		}
		if !fi.IsDir() {
			return 0, 0, nil, errors.Wrap(errors.Errorf("chunk snapshot %s is not a directory", name), "find last chunk snapshot")
		}

		splits := strings.Split(name[len(chunkSnapshotPrefix):], ".")
		if len(splits) != 2 {
			continue
		}

		idx, err := strconv.Atoi(splits[0])
		if err != nil {
			continue
		}
		offset, err := strconv.Atoi(splits[1])
		if err != nil {
			continue
		}

		if idx > maxIdx {
			maxIdx, maxOffset = idx, offset
			maxFileName = filepath.Join(h.opts.ChunkDirRoot, name)
		} else if idx == maxIdx {
			if offset > maxOffset {
				maxIdx, maxOffset = idx, offset
				maxFileName = filepath.Join(h.opts.ChunkDirRoot, name)
			}
		}
	}
	if maxFileName == "" {
		return 0, 0, nil, nil
	}

	dir := maxFileName
	snapIdx, snapOffset := maxIdx, maxOffset
	start := time.Now()

	type snapshotSegmentRef struct {
		name  string
		index int
	}
	var refs []snapshotSegmentRef
	if err := filepath.Walk(dir, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		relativePath := strings.TrimPrefix(strings.TrimPrefix(path, dir), string(os.PathSeparator))
		index, convErr := strconv.Atoi(relativePath)
		if convErr != nil {
			return nil
		}
		refs = append(refs, snapshotSegmentRef{name: relativePath, index: index})
		return nil
	}); err != nil {
		return snapIdx, snapOffset, nil, errors.Wrap(err, "open chunk snapshot")
	}
	sort.Slice(refs, func(i, j int) bool {
		return refs[i].index < refs[j].index
	})
	for i := 0; i < len(refs)-1; i++ {
		if refs[i].index+1 != refs[i+1].index {
			return snapIdx, snapOffset, nil, errors.Wrap(errors.New("segments are not sequential"), "open chunk snapshot")
		}
	}

	var segs []*wlog.Segment
	for _, ref := range refs {
		segment, openErr := wlog.OpenReadSegment(filepath.Join(dir, ref.name))
		if openErr != nil {
			return snapIdx, snapOffset, nil, errors.Wrap(openErr, "open chunk snapshot")
		}
		segs = append(segs, segment)
	}
	sr := wlog.NewSegmentBufReader(segs...)
	return h.applyChunkSnapshotRecords(sr, dir, snapIdx, snapOffset, start)
}

